python3 - <<'PY'
import pathlib,json,collections
p=pathlib.Path('classic/apps/web/src/earshot/catalog-data.json'); c=json.loads(p.read_text())
for k in c[0]:
 t=collections.Counter(type(s.get(k)).__name__ for s in c)
 if len(t)>1: print(k,t)
print('README regex literal',sum('.*' in line for line in pathlib.Path('classic/vendor/earshot/upstream/README.md').read_text().splitlines()))
for prefix in ['docs','skills','earshot']:
 n=0
 for f in (pathlib.Path('classic/vendor/earshot/upstream')/prefix).rglob('*'):
  if f.is_file():
   try: n+=sum('sound' in l.lower() for l in f.read_text().splitlines())
   except UnicodeDecodeError: pass
 print(prefix,n)
PY
cat .gitignore

